 import { Group, PlaneGeometry, MeshBasicNodeMaterial, DoubleSide } from 'three/webgpu';
import { uv, vec4, color, mix, smoothstep, sin, fract, mul } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();
  group.userData.handlers = {};
  group.userData.timelines = [];

  const width = 3.2;
  const height = 2.0;

  const ink = config?.intent?.visualSpec?.colors?.ink ?? '#16161d';
  const surface = config?.intent?.visualSpec?.colors?.surface ?? '#0b0b10';
  const accent = config?.intent?.visualSpec?.colors?.accent ?? '#ff2a38';

  const cardGeo = new PlaneGeometry(width, height);
  const cardMat = new MeshBasicNodeMaterial({
    transparent: true,
    side: DoubleSide,
    alphaTest: 0.02,
  });

  const yNorm = uv().y;
  const surfaceNode = color(surface);
  const inkNode = color(ink);
  const gradient = mix(surfaceNode, inkNode, smoothstep(0.0, 1.0, yNorm));

  const noiseCoord = uv().x.mul(1531.7).add(uv().y.mul(2899.3));
  const grain = fract(sin(noiseCoord).mul(43758.5453)).sub(0.5).mul(0.03);

  cardMat.colorNode = gradient.rgb.add(grain);

  const cardMesh = new ctx.THREE.Mesh(cardGeo, cardMat);
  cardMesh.position.z = 0.01;
  group.add(cardMesh);

  let pendingTexture = null;
  let isDisposed = false;

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      if (isDisposed) {
        tex.dispose();
        return;
      }
      tex.colorSpace = ctx.THREE.SRGBColorSpace;
      pendingTexture = tex;

      const sampled = ctx.THREE.texture(tex, uv());
      const shaded = mix(sampled.rgb, gradient.rgb, 0.08);
      const final = vec4(shaded.add(grain), sampled.a);
      cardMat.colorNode = final;
      cardMat.needsUpdate = true;
    }).catch(() => {});
  }

  const primitiveList = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const p of config.cinematicPrimitives) {
      if (p?.name && typeof ctx.primitives[p.name] === 'function') {
        try {
          primitiveList.push(ctx.primitives[p.name](group, p.params ?? {}));
        } catch {}
      }
    }
  }

  group.userData.cleanup = () => {
    isDisposed = true;
    primitiveList.forEach((p) => {
      try { p.cleanup?.(); } catch {}
    });
    group.userData.timelines.forEach((tl) => tl?.kill());
    gsap.killTweensOf(group);
    group.traverse((obj) => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) {
        if (Array.isArray(obj.material)) {
          obj.material.forEach((m) => {
            if (m.map?.dispose) m.map.dispose();
            m.dispose();
          });
        } else {
          if (obj.material.map?.dispose) obj.material.map.dispose();
          obj.material.dispose();
        }
      }
    });
    if (pendingTexture?.dispose) pendingTexture.dispose();
    pendingTexture = null;
  };

  return group;
}
